import fs from "node:fs";
const html = fs.readFileSync("index.html", "utf8");
const css = fs.readFileSync("src/styles.css", "utf8");
if (!html.includes('href="/src/styles.css"')) { console.error("index.html must link /src/styles.css"); process.exit(1); }
const open = (css.match(/{/g) || []).length, close = (css.match(/}/g) || []).length;
if (open !== close) { console.error("styles.css: unbalanced braces"); process.exit(1); }
for (const p of ["index.html", "src/styles.css", "src/app.js"]) { if (/uppercase|toUpperCase/i.test(fs.readFileSync(p, "utf8"))) { console.error(p + ": all-caps is forbidden by locked decision A1 (sentence case)"); process.exit(1); } }
console.log("build ok: " + open + " css rules");

