:root {
  --bg: #0B0C10;
  --text: #E5E7EB;
  --accent: #F2F0EB;
}
html[data-theme="light"] {
  --bg: #F7F5F0;
  --text: #1F2328;
  --accent: #0B0C10;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: Inter, system-ui, sans-serif;
}

.site-header {
  max-width: 1100px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 20px;
}

#theme-toggle {
  min-width: 44px;
  min-height: 44px;
  background: transparent;
  border: 1px solid var(--accent);
  color: var(--accent);
  font-size: 18px;
  font-family: inherit;
}

.logo {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  color: var(--accent);
  font-weight: 700;
  text-decoration: none;
}

.site-nav {
  display: flex;
  gap: 16px;
}

.site-nav a {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  padding: 0 4px;
  color: var(--text);
  text-decoration: none;
}

main {
  padding: 0 20px 40px;
  max-width: 1100px;
  margin: 0 auto;
}

h1 {
  max-width: 22ch;
  color: var(--accent);
  font-size: 36px;
  line-height: 1.15;
}

.lead {
  font-size: 18px;
  line-height: 1.5;
  max-width: 60ch;
}

.cta {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  padding: 12px 20px;
  border: 1px solid var(--accent);
  color: var(--accent);
  text-decoration: none;
}

.promo-strip {
  max-width: 100%;
  margin: 32px 0;
  padding: 12px 16px;
  background: #1A1C23;
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
}

.card {
  padding: 16px;
  background: #13151B;
}
